code.source:
#include <iostream>
using namespace std;

int main() {
    int a[4] = {5, 6, 7, 8};
    int* p = a;
    int* q = p + 1;
    cout << *q << endl;
    cout << (reinterpret_cast<char*>(q) - reinterpret_cast<char*>(p)) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[5] = {1, 2, 3, 4, 5};
    int* start = a;
    int* end = a + 5;
    cout << (end - start) << endl;
    cout << *(end - 1) << endl;
    return 0;
}

